    // Extract JSON from response
    const responseText = result.response;
    const jsonMatch = responseText.match(/\\{[^{}]*\\}/);

    if (!jsonMatch) {
      return res.status(500).json({ error: 'Failed to parse model response' });
    }

    const triageResult = JSON.parse(jsonMatch[0]);

    // Validate response structure

    const responseText = result.response;
    const jsonMatch = responseText.match(/\\{[^{}]*\\}/);

    if (!jsonMatch) {
      return res.status(500).json({ error: 'Failed to parse model response' });
    }

    const triageResult = JSON.parse(jsonMatch[0]);

    // Validate response structure
    if (!triageResult.status || !triageResult.reason || !triageResult.nextStep) {
      return res.status(400).json({ error: 'Invalid response structure' });
